  const handleGenerateTokenLibre = async (messageContent, emailSubject = "Notification : Votre Token d'accès AMM") => {
  // 1. Mamorona Token vaovao
  const characters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
  let randomString = '';
  for (let i = 0; i < 12; i++) {
    randomString += characters.charAt(Math.floor(Math.random() * characters.length));
  }
  const finalToken = "AMM-LIBRE-" + randomString;

  try {
    // 2. Mitahiry ny token ao amin'ny database
    const payload = { role: "LIBRE (VALIDATION INSCRIPTION)", token_miasa: finalToken };
    const uniqueId = `token_libre_${Date.now()}`;
    await fetch(`${BASE_URL}/token_pool/${uniqueId}.json`, { 
      method: 'PUT', 
      body: JSON.stringify(payload) 
    });
    
    setGeneratedTokenLibre(finalToken);
    pushLog("TOKEN GENERATION", `Namoaka Token Libre vaovao: ${finalToken}`);
    
    // 3. Fandefasana mailaka (Raha misy adiresy)
    if (tokenTargetEmail.trim()) {
      // Manolo ny token ao anaty message
      const finalMsg = messageContent.replace("${generatedTokenLibre}", finalToken);
      
      // Antsoina ny function EmailJS (Ity dia tsy mila password intsony)
      await sendNotificationEmail(tokenTargetEmail.trim(), emailSubject, finalMsg);
      
      alert(`Tafiditra soa aman-tsara! Nalefa tany amin'ny ${tokenTargetEmail}.`);
      setTokenTargetEmail("");
    } else {
      alert(`Token niteraka soa aman-tsara: ${finalToken}`);
    }
    
    fetchData();
  } catch (e) { 
    console.error("Error:", e);
    alert("Tsy nety niteraka na nandefa token. Jereo ny internet-nao."); 
  }
};

