  const WebDashboard = ({ data }) => {
    const balance = React.useMemo(() => {
      if (!Array.isArray(data)) return { miditra: 0, mivoaka: 0, net: 0 };
      
      const miditra = data.filter(t => t.karazana === 'MIDITRA').reduce((a, b) => a + Number(b.vola || 0), 0);
      const mivoaka = data.filter(t => t.karazana === 'MIVOAKA').reduce((a, b) => a + Number(b.vola || 0), 0);
      return { miditra, mivoaka, net: miditra - mivoaka };
    }, [data]);

    return (
      <View style={styles.balanceContainer}>
        <View style={styles.balanceBox}>
           <Text>💰 Miditra</Text>
           <Text style={{color:'green', fontWeight:'bold'}}>{balance.miditra.toLocaleString()} Ar</Text>
        </View>
        <View style={styles.balanceBox}>
           <Text>💸 Mivoaka</Text>
           <Text style={{color:'red', fontWeight:'bold'}}>{balance.mivoaka.toLocaleString()} Ar</Text>
        </View>
        <View style={[styles.balanceBox, {borderColor:'#0d3373', borderWidth:1}]}>
           <Text>⚖️ Net</Text>
           <Text style={{color:'#0d3373', fontWeight:'bold'}}>{balance.net.toLocaleString()} Ar</Text>
        </View>
      </View>
    );
  };

